"use client";

import { useEffect } from "react";
import { useRouter } from "next/navigation";
import { setPrefs, usePrefs } from "@/lib/prefs";
import { Account } from "./Account";
import styles from "./home.module.css";

/**
 * Placeholder home page. It sends first-time visitors to the intro questions
 * and shows what they answered, so the team can see the saved data. Build the
 * real home page here.
 */
export default function Home() {
  const router = useRouter();
  const prefs = usePrefs();

  useEffect(() => {
    if (prefs && !prefs.onboarded) router.replace("/onboarding");
  }, [prefs, router]);

  if (!prefs?.onboarded) return null;

  function answerAgain() {
    setPrefs({ onboarded: false });
    router.push("/onboarding");
  }

  const yesNo = (value: boolean | null) => (value === null ? "Not answered" : value ? "Yes" : "No");

  return (
    <main className={styles.home}>
      <div className={styles.top}>
        <p className={styles.wordmark}>AVision</p>
        <Account />
      </div>
      <h1 className={styles.title}>You&apos;re set up.</h1>
      <dl className={styles.answers}>
        <div>
          <dt>Student</dt>
          <dd>{yesNo(prefs.isStudent)}</dd>
        </div>
        {prefs.school && (
          <div>
            <dt>School</dt>
            <dd>{prefs.school}</dd>
          </div>
        )}
        <div>
          <dt>Takes MARTA</dt>
          <dd>{yesNo(prefs.takesMarta)}</dd>
        </div>
      </dl>
      <button type="button" className={styles.link} onClick={answerAgain}>
        Answer the questions again
      </button>
    </main>
  );
}
